  }
}

class MagicalArtifact extends Artifact {
  constructor(name, weight, manaCost) {
    super(name, weight);
    this.manaCost = manaCost;
  }

  castSpell() {
    return `Casting a generic spell with ${this.manaCost} mana.`;
  }
}

class HealingOrb extends MagicalArtifact {
  constructor(name, weight, manaCost, healAmount) {
    super(name, weight, manaCost);
    this.healAmount = healAmount;
  }

  castSpell() {
    return `${this.name} glows brightly and heals for ${this.healAmount} HP!`;
  }
}

